UPDATE questions SET
  choices = '["APIC from the original issuance up to the amount available, then retained earnings for the remainder","Treasury stock at the full reacquisition cost without any allocation to other equity accounts","Retained earnings for the full excess amount without reducing additional paid-in capital balances","A realized loss account reported in the other expenses section of the income statement"]',
  explanation = 'Under the par value method of treasury stock accounting, treasury stock is debited at par value, and APIC is debited for the amount originally credited to APIC when the shares were issued. Any excess of the reacquisition price over the original issuance price is debited to retained earnings (or APIC from treasury stock transactions, if a credit balance exists from prior treasury stock transactions). This method effectively reverses the original issuance entry. Choice B is incorrect because debiting treasury stock at the full reacquisition cost describes the cost method, not the par value method — the cost method records treasury stock at the price paid to reacquire the shares. Choice D is incorrect because treasury stock transactions are equity transactions that do not flow through the income statement under either method.'
